+          role="dialog"
+          aria-label="Replace manual enemy statistics"
+          data-confirm-frame={confirm.frame}
+          style={{ left: p.confirm.matrix.tx / 20, top: p.confirm.matrix.ty / 20 }}
+        >
+          {confirmRaster ? (
+            <CreatorRasterArt raster={confirmRaster} />
